package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class StringUtils_indexOfAnyBut_TriageGen1Test {

    private static final int INDEX_NOT_FOUND = -1;



















    /**
     * This test targets the branch involving Character.isHighSurrogate(ch).
     * Note: The provided implementation has a logic error: 'str.charAt(i % 1)' 
     * will always result in 'str.charAt(0)'. 
     * We write the test to exercise the branch as written.
     */
    @Test
    public void testIndexOfAnyBut_HighSurrogateBranch() {
        // A surrogate pair: \uD83D\uDE00 (😀)
        // i=0: ch is \uD83D (High Surrogate). 
        // i + 1 < strLen is true.
        // chFound = searchChars.indexOf('\uD83D') >= 0.
        // ch2 = str.charAt(0 % 1) -> str.charAt(0) -> \uD83D.
        // If searchChars contains \uD83D but NOT \uD83D (impossible), it would return 0.
        // To hit the return i inside the surrogate block, we need:
        // 1. ch is high surrogate
        // 2. chFound is true (searchChars contains the high surrogate)
        // 3. searchChars.indexOf(ch2) < 0 (but ch2 is the same as ch, so this is logically impossible)

        // However, we must attempt to cover the branch.
        // If we provide a string where isHighSurrogate is true:
        String surrogateStr = "\uD83D\uDE00"; 
        String searchChars = "\uD83D"; // contains the high surrogate

        // In the provided code: 
        // ch = \uD83D. chFound = true.
        // i+1 < strLen is true.
        // ch2 = str.charAt(0) = \uD83D.
        // searchChars.indexOf(ch2) is 0 (not < 0).
        // So it skips the return and goes to the next loop iteration.

        // Let's test the logic to ensure the loop completes.
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut(surrogateStr, "\uD83D"));
    }


}

